import math
from datetime import time, timedelta, datetime
from pprint import pprint

def weekly_slots(start_hour=8, end_hour=20, lesson_minutes=90, break_minutes=15):
    """Return list of (start_time_str, end_time_str) for one weekday."""
    slots = []
    start = datetime(2000,1,1,start_hour,0)
    lesson = timedelta(minutes=lesson_minutes)
    brk = timedelta(minutes=break_minutes)
    while start.time() <= time(hour=end_hour, minute=0):
        end = start + lesson
        if end.time() > time(hour=end_hour, minute=0):
            break
        slots.append((start.time().strftime("%H:%M"), end.time().strftime("%H:%M")))
        start = end + brk
    return slots

def schedule_semester(semester, semester_start="2025-10-01", semester_end="2026-01-31"):
    """
    semester: dict with keys 'student_count' and 'courses' (list of dicts)
    returns mapping course_id -> list of groups with start/end date & time
    """
    slots_per_day = weekly_slots()
    weekdays = ["Mon","Tue","Wed","Thu","Fri"]
    total_weekly_slots = len(slots_per_day) * len(weekdays)

    # compute total groups needed this semester
    total_groups = 0
    courses_with_groups = []
    for c in semester["courses"]:
        groups = c.get("cw_count")
        if groups is None:
            groups = math.ceil(semester["student_count"] / 15) + 1
        groups = max(1, int(groups))
        total_groups += groups
        courses_with_groups.append((c, groups))
    #print(courses_with_groups)
    #print(total_groups )

    if total_groups > total_weekly_slots:
        raise ValueError(
            f"Not enough weekly slots: need {total_groups}, but only {total_weekly_slots} available "
            "in Mon-Fri 08:00-20:00 with 1.5h+15m break. Add rooms/slots or extend schedule."
        )

    # build a flat list of (weekday, start, end) slots in deterministic order
    flat_slots = []
    for day in weekdays:
        for s,e in slots_per_day:
            flat_slots.append({"weekday": day, "start_time": s, "end_time": e})

    schedule = {}
    slot_idx = 0
    for course, groups in courses_with_groups:
        course_id = course.get("id", course.get("code", course.get("title")))
        schedule[course_id] = []
        for g in range(1, groups+1):
            slot = flat_slots[slot_idx]
            is_lecture = (g == 1 and groups > 1)  # first group reserved as lecture
            schedule[course_id].append({
                "group": g,
                "type": "lecture" if is_lecture else "cw",
                "start_date": semester_start,
                "end_date": semester_end,
                "weekday": slot["weekday"],
                "start_time": slot["start_time"],
                "end_time": slot["end_time"],
            })
            slot_idx += 1
    return schedule

def schedule_all(majors, semester_dates=None):
    """majors: {major_name: { 'semesters': [ {semester: n, courses: [...], student_count: x}, ...] } }
       semester_dates: optional dict {(major_name, semester_number): (start,end)} to override defaults
    """
    out = {}
    for major, meta in majors.items():
        out[major] = {}
        for sem in meta.get("semesters", []):
            sem_no = sem.get("semester")
            key = (major, sem_no)
            sstart, send = semester_dates.get(key) if semester_dates and key in semester_dates else ("2025-10-01","2026-01-31")
            out[major][sem_no] = schedule_semester(sem, semester_start=sstart, semester_end=send)
    return out

